using System.Diagnostics;
using System.IO;
using System.Net.Http;
using System.Security.Cryptography;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace TrMarketplaceHubDesktop;

public static class OrderInvoiceDialog
{
 static readonly Brush Teal=new SolidColorBrush(Color.FromRgb(17,112,120));

 public static void Show(OrderSnapshot original,string? directory,string? requestedAction=null,Action? changed=null)
 {
  var order=original.Copy();var settingsStore=new NesSettingsStore(directory is null?null:Path.Combine(directory,"nes.bin"));var documents=new NesDocumentStore(directory);var orders=new OrdersStore(directory);
  var window=new Window{Title=$"Sipariş ve fatura · {order.OrderId}",Width=920,Height=720,MinWidth=760,MinHeight=560,WindowStartupLocation=WindowStartupLocation.CenterOwner,Owner=Application.Current?.MainWindow,Background=Brushes.White};
  var root=new DockPanel{Margin=new Thickness(18)};window.Content=root;
  var footer=new DockPanel{Margin=new Thickness(0,12,0,0)};DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);var status=Text("Sipariş bilgilerini kontrol edip önce önizleme oluşturun.");status.FontWeight=FontWeights.SemiBold;footer.Children.Add(status);
  var close=ActionButton("Kapat",false);DockPanel.SetDock(close,Dock.Right);footer.Children.Add(close);close.Click+=(_,_)=>window.Close();
  var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto};root.Children.Add(scroll);var content=new StackPanel();scroll.Content=content;
  content.Children.Add(Text("Sipariş kartı",24));content.Children.Add(Text($"{order.Marketplace} · Mağaza {order.ShopId} · Sipariş {order.OrderId} · Paket {order.Shipments.FirstOrDefault()?.Id??"yok"}"));
  var flags=Text($"Kaynak durumu: {order.RawStatus}   •   Pazaryeri fatura durumu: {(order.MarketplaceInvoiceStatus.Length>0?order.MarketplaceInvoiceStatus:"Bilinmiyor")}   •   Toplam: {order.TotalLabel}");flags.Background=new SolidColorBrush(Color.FromRgb(238,246,247));flags.Padding=new Thickness(10);content.Children.Add(flags);
  var items=new DataGrid{AutoGenerateColumns=false,IsReadOnly=true,Height=Math.Min(210,75+order.Items.Count*34),Margin=new Thickness(0,8,0,10),HeadersVisibility=DataGridHeadersVisibility.Column};
  items.Columns.Add(Column("SKU","Sku",130));items.Columns.Add(Column("Ürün","Title",new DataGridLength(1,DataGridLengthUnitType.Star)));items.Columns.Add(Column("Adet","Quantity",65));items.Columns.Add(Column("Birim fiyat","UnitPrice",95));items.Columns.Add(Column("KDV %","VatRate",70));items.ItemsSource=order.Items;content.Children.Add(items);
  content.Children.Add(Text("Fatura alıcısı",18));var form=new Grid{Margin=new Thickness(0,2,0,8)};for(var i=0;i<4;i++)form.ColumnDefinitions.Add(new(){Width=i%2==0?new GridLength(125):new GridLength(1,GridUnitType.Star)});content.Children.Add(form);
  var defaultKind=OrderInvoiceRules.DefaultKind(order);var initialIdentity=order.TaxNumber;var fallbackApplied=false;
  if(string.IsNullOrWhiteSpace(initialIdentity)&&defaultKind==NesDocumentKind.EArchive&&!order.CommercialInvoice&&string.IsNullOrWhiteSpace(order.CustomerTaxOffice)){initialIdentity=NesReceiverIdentityResolver.IndividualEArchiveFallback;fallbackApplied=true;}
  var name=Field(form,"Ad / unvan",order.BillingName,0,0);var tax=Field(form,"VKN / TCKN",initialIdentity,0,2);var address=Field(form,"Adres",order.BillingAddress,1,0);var city=Field(form,"İl",order.BillingCity,1,2);var district=Field(form,"İlçe",order.BillingDistrict,2,0);var email=Field(form,"E-posta",order.BillingEmail,2,2);var phone=Field(form,"Telefon",order.CustomerPhone,3,0);var receiverAlias=Field(form,"Alıcı etiketi",string.Empty,3,2);
  var kind=new ComboBox{Width=190,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,3,0,4),ItemsSource=new[]{"e-Arşiv","e-Fatura"},SelectedIndex=defaultKind==NesDocumentKind.EInvoice?1:0};content.Children.Add(Text("Belge türü",14));content.Children.Add(kind);
  var identityNote=Text(fallbackApplied?"Bireysel e-Arşiv siparişinde TCKN gelmedi; 11111111111 otomatik uygulanacak.":"Kurumsal/e-Fatura alıcısında VKN veya TCKN zorunludur.");identityNote.Foreground=new SolidColorBrush(Color.FromRgb(76,92,110));content.Children.Add(identityNote);
  kind.SelectionChanged+=(_,_)=>{if(kind.SelectedIndex==0&&string.IsNullOrWhiteSpace(tax.Text)&&order.EInvoiceAvailable!=true&&!order.CommercialInvoice&&string.IsNullOrWhiteSpace(order.CustomerTaxOffice)){tax.Text=NesReceiverIdentityResolver.IndividualEArchiveFallback;fallbackApplied=true;identityNote.Text="Bireysel e-Arşiv siparişinde TCKN gelmedi; 11111111111 otomatik uygulanacak.";}else if(kind.SelectedIndex==1&&fallbackApplied&&tax.Text.Trim()==NesReceiverIdentityResolver.IndividualEArchiveFallback){tax.Clear();fallbackApplied=false;identityNote.Text="e-Fatura alıcısında Trendyol'dan gelen VKN veya TCKN zorunludur.";}};
  var actions=new WrapPanel{Margin=new Thickness(0,4,0,4)};content.Children.Add(actions);var prepare=ActionButton("1. Faturayı hazırla",true);var preview=ActionButton("2. NES önizlemesi",true);var open=ActionButton("Faturayı aç",false);actions.Children.Add(prepare);actions.Children.Add(preview);actions.Children.Add(open);preview.IsEnabled=false;open.IsEnabled=order.InvoiceUuid.Length>0;
  var nesApproval=new CheckBox{Content="Fatura türünü, alıcıyı, satırları, tutarı ve KDV'yi kontrol ettim; NES'e gönderilsin.",Margin=new Thickness(2,9,2,4)};content.Children.Add(nesApproval);var send=ActionButton("3. Onayla ve NES'e gönder",true);send.IsEnabled=false;content.Children.Add(send);
  var isTrendyol=order.Marketplace.Equals("Trendyol",StringComparison.OrdinalIgnoreCase);
  var trendyolApproval=new CheckBox{Content="NES faturası gönderilince bu Trendyol paketine PDF olarak da yüklensin.",Margin=new Thickness(2,14,2,4),IsEnabled=isTrendyol};content.Children.Add(trendyolApproval);var upload=ActionButton("Trendyol'a faturayı yükle",true);upload.IsEnabled=isTrendyol&&order.InvoiceUuid.Length>0;content.Children.Add(upload);
  content.Children.Add(Text("NES bağlantı ve firma ayarları NES e-Fatura ekranından yönetilir. Burada sipariş seçimi, önizleme, gönderim ve pazaryerine yükleme tek akışta yapılır."));

  NesDraft? draft=null;NesUblDraft? ubl=null;string? previewPath=null;var busy=false;
  NesSettings Settings()=>settingsStore.Load()??throw new InvalidOperationException("Önce NES e-Fatura ekranında bağlantı ve firma ayarlarını kaydedin.");
  OrderSnapshot Capture(){var copy=order.Copy();copy.BillingName=name.Text.Trim();copy.TaxNumber=tax.Text.Trim();copy.BillingAddress=address.Text.Trim();copy.BillingCity=city.Text.Trim();copy.BillingDistrict=district.Text.Trim();copy.BillingEmail=email.Text.Trim();copy.CustomerPhone=phone.Text.Trim();return copy;}
  async Task Run(Func<Task> action){if(busy)return;busy=true;content.IsEnabled=false;try{await action();}catch(ArgumentException ex){status.Text=ex.Message;}catch(InvalidOperationException ex){status.Text=MarketplaceConnectionStore.Redact(ex.Message);}catch(OperationCanceledException){status.Text="İşlem zaman aşımına uğradı veya iptal edildi; kayıtları yenileyin.";}catch{status.Text="Fatura işlemi tamamlanamadı; mevcut kayıtlar korundu.";}finally{busy=false;content.IsEnabled=true;}}
  void RestoreExistingDraft()
  {
   var existing=documents.List().FirstOrDefault(x=>x.Marketplace==order.Marketplace&&x.ShopId==order.ShopId&&x.OrderId==order.OrderId);
   if(existing is null)return;
   if(existing.State=="Sent"&&Guid.TryParse(existing.NesUuid,out _)&&existing.NesDocumentNumber.Length>0)
   {
    if(order.InvoiceUuid.Length==0)orders.AttachNesInvoice(order.Marketplace,order.ShopId,order.OrderId,existing.Kind==NesDocumentKind.EInvoice?"e-Fatura":"e-Arşiv",existing.NesUuid,existing.NesDocumentNumber,"Gönderildi",existing.IssueAt);
    order.InvoiceUuid=existing.NesUuid;order.InvoiceNumber=existing.NesDocumentNumber;order.InvoiceType=existing.Kind==NesDocumentKind.EInvoice?"e-Fatura":"e-Arşiv";order.InvoiceIssuedAt=existing.IssueAt;open.IsEnabled=true;upload.IsEnabled=isTrendyol;status.Text=$"{existing.NesDocumentNumber} NES'e gönderilmiş. Faturayı açabilir veya Trendyol'a yükleyebilirsiniz.";changed?.Invoke();return;
   }
   if(existing.State!="Previewed")return;
   try
   {
    var settings=Settings();var captured=Capture();var identity=NesReceiverIdentityResolver.Resolve(captured,existing.Kind);captured.TaxNumber=identity.Value;tax.Text=identity.Value;kind.SelectedIndex=existing.Kind==NesDocumentKind.EInvoice?1:0;
    var rebuilt=NesUblBuilder.Build(settings,captured,existing.Kind,existing.DocumentNumber,Guid.Parse(existing.LocalUuid),existing.IssueAt);
    if(!string.Equals(rebuilt.Hash,existing.ContentHash,StringComparison.OrdinalIgnoreCase)){status.Text=$"{existing.DocumentNumber} önizlemesinden sonra sipariş veya ayarlar değişmiş. Güvenli gönderim için faturayı yeniden hazırlayın.";return;}
    draft=existing;ubl=rebuilt;preview.IsEnabled=true;send.IsEnabled=true;previewPath=Path.Combine(directory??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MonoBridgeDesktop"),"nes-previews",existing.DocumentNumber+".html");status.Text=$"{existing.DocumentNumber} NES önizlemesi hazır. Kontrol onayını işaretleyip gönderebilirsiniz.";
   }
   catch(Exception ex) when(ex is ArgumentException or InvalidOperationException){status.Text=MarketplaceConnectionStore.Redact(ex.Message);}
  }
  prepare.Click+=async(_,_)=>await Run(()=>{OrderInvoiceRules.ValidateCanInvoice(order);var captured=Capture();var settings=Settings();var documentKind=kind.SelectedIndex==1?NesDocumentKind.EInvoice:NesDocumentKind.EArchive;var identity=NesReceiverIdentityResolver.Resolve(captured,documentKind);captured.TaxNumber=identity.Value;tax.Text=identity.Value;var series=documentKind==NesDocumentKind.EInvoice?settings.EInvoiceSeries:settings.EArchiveSeries;var fingerprint=Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(new{captured,documentKind,settings.CompanyTitle,settings.TaxNumber,settings.Address,settings.City,settings.District,ReceiverAlias=receiverAlias.Text.Trim()})));draft=documents.Prepare(captured.Marketplace,captured.ShopId,captured.OrderId,documentKind,series,fingerprint);ubl=NesUblBuilder.Build(settings,captured,documentKind,draft.DocumentNumber,Guid.Parse(draft.LocalUuid),draft.IssueAt);draft=documents.Prepare(captured.Marketplace,captured.ShopId,captured.OrderId,documentKind,series,ubl.Hash);preview.IsEnabled=true;send.IsEnabled=false;nesApproval.IsChecked=false;status.Text=$"{draft.DocumentNumber} hazır · {(identity.UsedEArchiveFallback?"Bireysel alıcı kimliği 11111111111 · ":"")}Matrah {ubl.TaxExclusiveAmount:0.00} · KDV {ubl.TaxAmount:0.00} · Genel toplam {ubl.PayableAmount:0.00} {captured.Currency}. Şimdi önizlemeyi alın.";return Task.CompletedTask;});
  preview.Click+=async(_,_)=>await Run(async()=>{if(draft is null||ubl is null)throw new InvalidOperationException("Önce faturayı hazırlayın.");using var http=Http();var bytes=await new NesConnection(http).PreviewAsync(Settings(),draft.Kind,ubl.Xml);documents.MarkPreviewed(draft);var previewDirectory=Path.Combine(directory??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MonoBridgeDesktop"),"nes-previews");Directory.CreateDirectory(previewDirectory);previewPath=Path.Combine(previewDirectory,draft.DocumentNumber+".html");File.WriteAllBytes(previewPath,bytes);send.IsEnabled=true;status.Text="NES önizlemesi alındı. Görüntüyü açıp kontrol edin, sonra onay kutusunu işaretleyin.";if(File.Exists(previewPath))Process.Start(new ProcessStartInfo(previewPath){UseShellExecute=true});});
  send.Click+=async(_,_)=>await Run(async()=>{if(nesApproval.IsChecked!=true)throw new InvalidOperationException("NES gönderimi için kontrol onayını işaretleyin.");if(draft is null||ubl is null||draft.State!="Previewed")throw new InvalidOperationException("Güncel NES önizlemesi olmadan gönderim yapılamaz.");var captured=Capture();try{using var http=Http();var result=await new NesConnection(http).UploadAsync(Settings(),draft.Kind,ubl.Xml,captured,receiverAlias.Text.Trim(),true);var number=result.DocumentNumber.Length>0?result.DocumentNumber:draft.DocumentNumber;documents.MarkSent(draft,result.Uuid,number);orders.AttachNesInvoice(captured.Marketplace,captured.ShopId,captured.OrderId,draft.Kind==NesDocumentKind.EInvoice?"e-Fatura":"e-Arşiv",result.Uuid,number,"Gönderildi");order.InvoiceUuid=result.Uuid;order.InvoiceNumber=number;order.InvoiceType=draft.Kind==NesDocumentKind.EInvoice?"e-Fatura":"e-Arşiv";order.InvoiceIssuedAt=DateTimeOffset.Now;open.IsEnabled=true;upload.IsEnabled=isTrendyol;send.IsEnabled=false;nesApproval.IsChecked=false;changed?.Invoke();if(trendyolApproval.IsChecked==true){await UploadTrendyol();status.Text=$"NES faturası gönderildi ve Trendyol'a yüklendi: {number}.";}else status.Text=$"NES faturası gönderildi: {number}. Trendyol yüklemesini ayrıca yapabilirsiniz.";}catch(OperationCanceledException){documents.MarkUnknown(draft);send.IsEnabled=false;throw new InvalidOperationException("NES gönderiminin sonucu belirsiz. Giden faturaları kontrol etmeden yeniden göndermeyin.");}});
  async Task<string> Download(){if(order.InvoiceUuid.Length==0)throw new InvalidOperationException("Bu siparişe bağlı NES faturası bulunamadı.");var documentKind=order.InvoiceType.Contains("Arşiv",StringComparison.OrdinalIgnoreCase)?NesDocumentKind.EArchive:NesDocumentKind.EInvoice;using var http=Http();var bytes=await new NesConnection(http).DownloadPdfAsync(Settings(),documentKind,order.InvoiceUuid);var folder=Path.Combine(directory??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MonoBridgeDesktop"),"nes-invoices");Directory.CreateDirectory(folder);var safe=string.Concat(order.InvoiceNumber.Where(char.IsLetterOrDigit));var path=Path.Combine(folder,(safe.Length>0?safe:order.InvoiceUuid)+".pdf");File.WriteAllBytes(path,bytes);return path;}
  open.Click+=async(_,_)=>await Run(async()=>{var path=await Download();Process.Start(new ProcessStartInfo(path){UseShellExecute=true});status.Text="Fatura PDF dosyası açıldı.";});
  async Task UploadTrendyol(){if(trendyolApproval.IsChecked!=true)throw new InvalidOperationException("Trendyol yüklemesi için onay kutusunu işaretleyin.");if(!long.TryParse(order.Shipments.FirstOrDefault()?.Id,out var packageId)||packageId<=0)throw new InvalidOperationException("Geçerli Trendyol paket kimliği bulunamadı.");var credentials=TrendyolOrderWriteGuard.Resolve(directory,order.ShopId);var path=await Download();using var http=Http();await new TrendyolInvoiceClient(credentials,http).UploadPdfAsync(packageId,order.InvoiceNumber,order.InvoiceIssuedAt??DateTimeOffset.Now,await File.ReadAllBytesAsync(path));orders.MarkMarketplaceInvoiceUploaded(order.Marketplace,order.ShopId,order.OrderId);order.MarketplaceInvoiceStatus="Invoiced";trendyolApproval.IsChecked=false;changed?.Invoke();}
  upload.Click+=async(_,_)=>await Run(async()=>{await UploadTrendyol();status.Text="Fatura PDF dosyası Trendyol paketine yüklendi ve sipariş kaydı güncellendi.";});
  if(requestedAction=="open"&&open.IsEnabled)window.Loaded+=async(_,_)=>await Run(async()=>{var path=await Download();Process.Start(new ProcessStartInfo(path){UseShellExecute=true});});
  window.Loaded+=(_,_)=>RestoreExistingDraft();window.ShowDialog();
 }

 static HttpClient Http()=>new(new HttpClientHandler{AllowAutoRedirect=false}){Timeout=TimeSpan.FromSeconds(60)};
 static TextBlock Text(string value,int size=13)=>new(){Text=value,FontSize=size,TextWrapping=TextWrapping.Wrap,Foreground=Brushes.DarkSlateGray,Margin=new Thickness(2,3,2,7)};
 static Button ActionButton(string label,bool primary)=>new(){Content=label,Padding=new Thickness(13,7,13,7),Margin=new Thickness(2,3,6,3),Background=primary?Teal:Brushes.White,Foreground=primary?Brushes.White:Brushes.DarkSlateGray};
 static DataGridTextColumn Column(string header,string path,DataGridLength width)=>new(){Header=header,Binding=new System.Windows.Data.Binding(path),Width=width};
 static DataGridTextColumn Column(string header,string path,double width)=>Column(header,path,new DataGridLength(width));
 static TextBox Field(Grid grid,string label,string value,int row,int column){while(grid.RowDefinitions.Count<=row)grid.RowDefinitions.Add(new(){Height=GridLength.Auto});var title=Text(label);Grid.SetRow(title,row);Grid.SetColumn(title,column);grid.Children.Add(title);var box=new TextBox{Text=value,Margin=new Thickness(3),MinWidth=150};Grid.SetRow(box,row);Grid.SetColumn(box,column+1);grid.Children.Add(box);return box;}
}
